contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        c.transferOwnership(newOwner);
        assert(c.owner() == newOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter = c.owner();
        assert(reverted ? ownerAfter == ownerBefore : ownerAfter == newOwner);
    }

    receive() external payable {}
}

