contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(this) && caller != address(0), "caller must be a non-owner address");
        address beforeOwner = c.owner();
        bool reverted;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        reverted = !ok;
        assert(reverted && c.owner() == beforeOwner);
    }

    receive() external payable {}
}
